#include "bsp.h"
#include "usart.h"

static int16_t target_left, target_right;

void BSP_Log(const char *text)
{
    while (*text) {
        uint32_t began = HAL_GetTick();
        while (!LL_USART_IsActiveFlag_TXE(USART1)) {
            if ((uint32_t)(HAL_GetTick() - began) >= 10U) {
                car_command('s', HAL_GetTick());
                uint32_t mask = __get_PRIMASK();
                __disable_irq();
                Motion_Stop(STOP_FREE);
                __set_PRIMASK(mask);
                return;
            }
        }
        LL_USART_TransmitData8(USART1, (uint8_t)*text++);
    }
}

void BSP_Init(void)
{
    PID_Param_Init();
    Motion_Stop(STOP_FREE);
    Bsp_Tim_Init();
    BSP_Log("LineCar baseline: STOP. f=forward 1s, l=line 10s, s=stop\r\n");
    BSP_Log("lesson01: hello from my car\r\n");
}

void BSP_Loop(void)
{
    uint32_t now = HAL_GetTick();
    if (LL_USART_IsActiveFlag_ORE(USART1) || LL_USART_IsActiveFlag_FE(USART1) ||
        LL_USART_IsActiveFlag_NE(USART1)) {
        LL_USART_ClearFlag_ORE(USART1);
        car_command('s', now);
    }
    for (int i = 0; i < 8 && LL_USART_IsActiveFlag_RXNE(USART1); ++i)
        car_command(LL_USART_ReceiveData8(USART1), now);

    uint8_t raw = (IN_X1 != 0) | ((IN_X2 != 0) << 1) |
                  ((IN_X3 != 0) << 2) | ((IN_X4 != 0) << 3);
    car_irtrack((uint8_t)(raw ^ 15U), now, &target_left, &target_right);

    // The timer ISR reads all four targets; update them together.
    uint32_t mask = __get_PRIMASK();
    __disable_irq();
    if (target_left == 0 && target_right == 0)
        Motion_Stop(STOP_FREE);
    else
        Motion_Set_Speed(target_left, target_left, target_right, target_right);
    __set_PRIMASK(mask);

    static uint32_t last_report;
    if ((uint32_t)(now - last_report) >= 200U) {
        last_report = now;
        float speeds[4];
        mask = __get_PRIMASK();
        __disable_irq();
        Motion_Get_Motor_Speed(speeds);
        __set_PRIMASK(mask);
        char text[160];
        snprintf(text, sizeof text,
                 "mode=%s ir=%u%u%u%u target=%d,%d speed=%d,%d,%d,%d\r\n",
                 car_mode_name(), !!(raw & 1), !!(raw & 2), !!(raw & 4), !!(raw & 8),
                 target_left, target_right,
                 (int)speeds[0], (int)speeds[1], (int)speeds[2], (int)speeds[3]);
        BSP_Log(text);
    }
    HAL_Delay(2);
}

