static CarMode mode = CAR_STOPPED;
static uint32_t started_at;

void car_command(uint8_t command, uint32_t now)
{
    switch (command) {
    case 'f': mode = CAR_FORWARD; started_at = now; break;
    case 'l': mode = CAR_LINE; started_at = now; break;
    case '\r': case '\n': break;
    default: mode = CAR_STOPPED; break;  // s or an unknown command stops the car.
    }
}

CarMode car_mode(void) { return mode; }

const char *car_mode_name(void)
{
    static const char *names[] = {"stop", "forward", "line", "lost", "wide", "timeout"};
    return names[mode];
}

void car_irtrack(uint8_t black_mask, uint32_t now, int16_t *left, int16_t *right)
{
    *left = *right = 0;
    if (mode != CAR_FORWARD && mode != CAR_LINE) return;
    uint32_t limit = mode == CAR_FORWARD ? 1000U : 10000U;
    if ((uint32_t)(now - started_at) >= limit) {
        mode = CAR_TIMEOUT;
        return;
    }
    if (mode == CAR_FORWARD) {
        *left = *right = 100;  // mm/s; one-second bench test.
        return;
    }
    black_mask &= 15U;
    if (black_mask == 0 || black_mask == 15) {
        mode = black_mask == 0 ? CAR_LOST : CAR_WIDE;
        return;
    }
    // shortcut: X2,X1,X3,X4 order is inferred from the vendor example; verify each probe before floor tests.
    const int weights[4] = {-1, -3, 1, 3};
    int sum = 0, count = 0;
    for (int i = 0; i < 4; ++i) {
        if (black_mask & (1U << i)) { sum += weights[i]; ++count; }
    }
    int correction = 40 * sum / count;
    int l = 120 + correction, r = 120 - correction;
    *left = l < 0 ? 0 : l > 180 ? 180 : l;
    *right = r < 0 ? 0 : r > 180 ? 180 : r;
}

